import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { IGridQuery } from './GridSystem';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';
import { HallEvents } from '../HallEvents';
import { GameData } from '../../Core/Data/GameData';
import { worldToGrid } from '../Config/GridConfig';
import type { GhostState } from '../Data/GhostState';


export class GhostSystem implements System {

    private _world: World = null!;
    private _typeId = '';
    private _gridX = -1;
    private _gridY = -1;
    private _hasPos = false;


    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.BUILD_TYPE_SELECTED, this._onTypeSelected, this);
        world.bus.on(HallEvents.INPUT_DRAG, this._onDrag, this);
        world.bus.on(HallEvents.BUILD_CANCEL, this._onCancel, this);
        world.bus.on(HallEvents.BUILD_COMPLETED, this._onBuildDone, this);
        world.bus.on(HallEvents.BUILD_FAILED, this._onBuildFailed, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_TYPE_SELECTED, this._onTypeSelected, this);
        world.bus.off(HallEvents.INPUT_DRAG, this._onDrag, this);
        world.bus.off(HallEvents.BUILD_CANCEL, this._onCancel, this);
        world.bus.off(HallEvents.BUILD_COMPLETED, this._onBuildDone, this);
        world.bus.off(HallEvents.BUILD_FAILED, this._onBuildFailed, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onTypeSelected(typeId: string): void {
        if (!BUILDING_CONFIG[typeId]) return;
        this._typeId = typeId;
        this._hasPos = false;
        this._emitState();
    }

    private _onDrag(wx: number, wy: number): void {
        if (!this._typeId) return;           // 不在 PLACING，忽略
        const g = worldToGrid(wx, wy);
        if (!g) return;                       // 拖到网格外，保持上次位置
        this._gridX = g.gridX;
        this._gridY = g.gridY;
        this._hasPos = true;
        this._emitState();
    }

    private _onCancel(): void {
        this._typeId = '';
        this._hasPos = false;
        this._emitState();
    }

    private _onBuildDone(): void {
        this._onCancel();
    }

    private _onBuildFailed(): void {
        this._emitState();                    // 失败保持 PLACING，只是重算 valid
    }

    private _emitState(): void {
        if (!this._typeId || !this._hasPos) {
            this._world.bus.emit(HallEvents.GHOST_STATE_CHANGED, {
                active: false, typeId: '', gridX: 0, gridY: 0, valid: false,
            } as GhostState);
            return;
        }

        const cfg = BUILDING_CONFIG[this._typeId];
        const coins = GameData.profile.data.coins;
   
        const affordable = coins >= cfg.cost;
        const empty = 

        this._world.bus.emit(HallEvents.GHOST_STATE_CHANGED, {
            active: true,
            typeId: this._typeId,
            gridX: this._gridX,
            gridY: this._gridY,
            valid: empty && affordable,
        } as GhostState);
    }
}